head.script:
// 테스트 설명, 유효성 값 설정
//  _1 : columnInfo 파라미터를 Column 인덱스(숫자)로 지정하는 분리 샘플 (_2 는 Column ID 지정)
scwin.tData = {
    "description" : "[gridView > M > setAllowChar]<br/>Body Column 정보를 사용하여 특정 Column 의 allowChar 속성을 설정합니다.",
    "validation" : [
        "Body Column 이 inputType='text','textImage','secret' 인 경우에 동작합니다.",
        "columnInfo(필수) 파라미터로 allowChar 속성을 설정하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "allowChar(필수) 파라미터로 정규식의 문자클래스 형식으로 특정 Column 에 입력이 가능한 문자 집합을 설정할 수 있어야 합니다.",
        "allowChar(필수) 파라미터는 정규식의 문자클래스에서 특수문자로 처리되는 ']', '-', '\\' 등의 문자는 이스케이프 처리하여 설정해야 합니다.",
        "allowChar(필수) 파라미터의 설정값은 정규식의 문자클래스('[...]' 처리)에 반영되어 입력이 가능한 문자를 찾는데 사용됩니다.",
        "setAllowChar() 메소드는 Column 단위로 적용되고, setCellAllowChar() 메소드는 'custom' Column 의 특정 Cell 에만 적용됩니다.",
        "setAllowChar() 메소드와 setIgnoreChar() 메소드를 동일 Column 에 적용할 수 있으며 이 경우 allowChar 규칙이 먼저 허용 문자 외를 제거하고, ignoreChar 규칙이 추가로 지정 문자를 제거하는 순서로 동작합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body Column 인덱스 0 = col1(text), 인덱스 1 = col2(text, 숨김), 인덱스 2 = col3(textImage), 인덱스 3 = col4(secret), 인덱스 4 = col5(textarea).\n[절차] columnInfo / allowChar 선택 -> setAllowChar 실행 -> 해당 Column 의 셀을 더블클릭해 허용되지 않은 문자를 섞어 입력하고 포커스 아웃 (onafteredit 로 확정값 출력).\n[확인] 인덱스 2 지정 시 숨김 Column 을 포함해 세어 세번째 Column(col3) 에 적용되는지 / 인덱스 4(textarea) 지정 시 동작 대상 inputType 이 아니라 미동작인지 / 같은 Column 의 여러 Row 를 편집했을 때 결과 / setIgnoreChar 를 이어 실행한 뒤 다시 입력했을 때 결과를 확인한다."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (영문 대소문자 + 숫자 + 특수문자 혼합 -> 편집 시 allowChar 필터 결과가 드러나도록)
    //  ※ 공통 createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성하므로 col5 를 위해 인라인 생성한다.
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    dlt_bind.setJSON([
        { "col1": "Ab1-2c", "col2": "Hi12!x", "col3": "9a8B7c", "col4": "X9-y8Z", "col5": "Pp1-2q" },
        { "col1": "Zz9_8x", "col2": "Wo34?y", "col3": "1q2W3e", "col4": "Q1-w2R", "col5": "Rr3_4s" },
        { "col1": "Mn5,6P", "col2": "Te56#z", "col3": "5t6Y7u", "col4": "E3-r4T", "col5": "Ss5,6t" },
        { "col1": "Kk7.8L", "col2": "Co78@w", "col3": "8i9O0p", "col4": "T5-y6U", "col5": "Tt7.8u" }
    ]);

    // target 생성
    //  Body Column 을 인덱스 기준으로 구성한다.
    //   인덱스 0 : col1  inputType="text"       (동작 대상)
    //   인덱스 1 : col2  inputType="text"       (★ setColumnVisible(1,false) 로 숨김 -> 인덱스는 1 을 유지)
    //   인덱스 2 : col3  inputType="textImage"  (동작 대상)
    //   인덱스 3 : col4  inputType="secret"     (동작 대상)
    //   인덱스 4 : col5  inputType="textarea"   (동작 대상 아님 -> 미동작)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" ev:onafteredit="scwin.target1_onafteredit" id="" style="width:680px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" inputType="text" id="hcol1" value="0 : col1 (text)"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="hcol2" value="1 : col2 (text, 숨김)"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="hcol3" value="2 : col3 (textImage)"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="hcol4" value="3 : col4 (secret)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol5" value="4 : col5 (textarea)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="140" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="140" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="140" inputType="secret" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="*" inputType="textarea" id="col5" dataList="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // ★ 두번째 Column(인덱스 1) 을 숨김 -> "숨겨진 Column 도 포함하여 인덱스가 설정" 검증용
    scwin.target1.setColumnVisible(1, false);
}



// setAllowChar 실행 : columnInfo 를 Column 인덱스(숫자)로 전달하여 해당 Column 의 allowChar 속성을 설정
//  쌍이 되는 get 메소드가 없으므로 설정 후 해당 Column 의 cellInfo 에 반영된 allowChar 값을 함께 출력한다.
scwin.btn_setAllowChar_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let allowChar = par_allowChar.getValue();

    let ret = scwin.target1.setAllowChar(columnInfo, allowChar);
    let applied = scwin.target1.getCellInfo(columnInfo).options.allowChar;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setAllowChar(" + columnInfo + ", '" + allowChar + "')"
        + (ret === false ? " : 동작 대상 inputType 아님 -> 미동작" : " -> Column 에 설정된 allowChar : '" + applied + "'"));
}



// setIgnoreChar 실행 : 동일 Column 에 ignoreChar 규칙을 추가로 적용 (allowChar 적용 후 ignoreChar 가 추가 제거)
scwin.btn_setIgnoreChar_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let ignoreChar = par_ignoreChar.getValue();

    let ret = scwin.target1.setIgnoreChar(columnInfo, ignoreChar);
    let applied = scwin.target1.getCellInfo(columnInfo).options.ignoreChar;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setIgnoreChar(" + columnInfo + ", '" + ignoreChar + "')"
        + (ret === false ? " : 동작 대상 inputType 아님 -> 미동작" : " -> Column 에 설정된 ignoreChar : '" + applied + "'"));
}



// 셀 편집 종료(포커스 아웃) 시 발생 : 편집 중 입력한 문자에 allowChar 규칙이 적용된 확정값을 출력
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    wf_body_bottom.getObj("scwin").setReturnValue(
        "onafteredit | Row " + rowIndex + " / Column 인덱스 " + columnIndex + " 편집 확정값 : '" + value + "'");
}
